/**
 * Visual regression PoC — darkmode coverage.
 *
 * Captures a single sample document page in both light and dark themes
 * and compares against baseline PNGs stored under `__screenshots__/`.
 * Generated by the `visual-regression` PDCA cycle (2026-05-24).
 *
 * Re-baseline locally with:
 *   pnpm playwright test tests/e2e/visual-darkmode.spec.ts --update-snapshots
 *
 * The page uses `white-paper-realtime-edit-design` which contains chart,
 * gantt, flow (mermaid), and several block surfaces — exercising every
 * darkmode integration path landed in chart-darkmode, gantt-darkmode,
 * orgchart-darkmode, block-darkmode-batch, and chart-libs-darkmode.
 */
import { test, expect } from '@playwright/test'
import { loginAsAdmin } from './helpers'

const SAMPLE_SLUG = 'white-paper-realtime-edit-design'

test.describe('visual: darkmode regression PoC', () => {
  test.beforeEach(async ({ page }) => {
    await loginAsAdmin(page)
  })

  test('light mode renders the sample doc consistently', async ({ page }) => {
    await page.addInitScript(() => {
      document.documentElement.classList.remove('dark')
      document.documentElement.removeAttribute('data-theme')
    })
    await page.goto(`/docs/${encodeURIComponent(SAMPLE_SLUG)}`)
    // Wait for mermaid + charts to render. The article is the doc body.
    await page.waitForSelector('article', { timeout: 15_000 })
    // Allow a generous settle window for async chart libs (echarts,
    // mermaid, recharts ResponsiveContainer measure).
    await page.waitForTimeout(2_000)
    await expect(page).toHaveScreenshot('doc-light.png', {
      fullPage: true,
      maxDiffPixelRatio: 0.02,
      animations: 'disabled',
    })
  })

  test('dark mode renders the sample doc consistently', async ({ page }) => {
    // ⚠ ThemeProvider 가 system 모드면 마운트 때 prefers-color-scheme 으로 class 를 다시 정한다 — 아래 initScript 의
    // 'dark' 는 지워지고 doc-dark 기준 그림은 실제로 밝은 화면이다(2026-10-24 확인). 새 시험은 emulateMedia 를 쓴다.
    await page.addInitScript(() => {
      document.documentElement.classList.add('dark')
      document.documentElement.setAttribute('data-theme', 'dark')
    })
    await page.goto(`/docs/${encodeURIComponent(SAMPLE_SLUG)}`)
    await page.waitForSelector('article', { timeout: 15_000 })
    await page.waitForTimeout(2_000)
    await expect(page).toHaveScreenshot('doc-dark.png', {
      fullPage: true,
      maxDiffPixelRatio: 0.02,
      animations: 'disabled',
    })
  })
})

// docs/llm-wiki C5 — 소속 → 팀 관리자 화면. 테마는 emulateMedia 로 고른다(앱이 system 모드로 따르는 길).
// 대응 줄 · 팀 목록은 dev 데이터라 가리고(mask) 화면 틀만 본다.
test.describe('visual: admin aff-team-map (light · dark)', () => {
  test.beforeEach(async ({ page }) => {
    await loginAsAdmin(page)
  })

  for (const scheme of ['light', 'dark'] as const) {
    test(`${scheme} mode renders the aff-team-map page consistently`, async ({ page }) => {
      await page.emulateMedia({ colorScheme: scheme })
      await page.goto('/admin/aff-team-map')
      await page.getByTestId('aff-team-map-table').waitFor()
      // 밝을 때 ThemeProvider 는 data-theme 을 지운다 — 있는지가 아니라 'dark' 인지를 본다.
      if (scheme === 'dark') await expect(page.locator('html')).toHaveAttribute('data-theme', 'dark')
      else await expect(page.locator('html')).not.toHaveAttribute('data-theme', 'dark')
      await expect(page.getByTestId('aff-team-map-page')).toHaveScreenshot(`aff-team-map-${scheme}.png`, {
        mask: [page.getByTestId('aff-team-map-table').locator('tbody'), page.getByTestId('team-select')],
        maxDiffPixelRatio: 0.02,
        animations: 'disabled',
      })
    })
  }
})

